import{_ as a,o as i,c as t,a6 as s}from"./chunks/framework.CKIbuWFA.js";const m=JSON.parse('{"title":"Runtimes de plugins y límites de confianza","description":"","frontmatter":{"title":"Runtimes de plugins y límites de confianza","docId":"developer.plugins.runtimes","translationKey":"developer.plugins.runtimes","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6a249fa36fa53f3bfe7da57fdd25a445e593517946f80ac7e891b54d95cdc17d","translationRevision":"55e734123a4444711d8ab35c8c8540eb121d6993900cd047a5210333578af3b0","order":260},"headers":[],"relativePath":"es/developer/plugins/runtimes.md","filePath":"es/developer/plugins/runtimes.md","lastUpdated":1794611623000}'),o={name:"es/developer/plugins/runtimes.md"};function n(d,e,r,l,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="plugin-runtimes-and-trust-limits" tabindex="-1">Runtimes de plugins y límites de confianza <a class="header-anchor" href="#plugin-runtimes-and-trust-limits" aria-label="Permalink to &quot;Runtimes de plugins y límites de confianza {#plugin-runtimes-and-trust-limits}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Elige un formato ejecutable cuyas dependencias y confianza correspondan al host. Lee la <a href="./">introducción</a>, valida el manifiesto contra la compilación real e inspecciona restricciones de plataforma antes de cargar código. Compatibilidad de protocolo, ABI y permisos son comprobaciones independientes.</p><h2 id="choose-an-implemented-runtime" tabindex="-1">Elegir un runtime implementado <a class="header-anchor" href="#choose-an-implemented-runtime" aria-label="Permalink to &quot;Elegir un runtime implementado {#choose-an-implemented-runtime}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Runtime</th><th>Ejecución</th><th>Confianza y portabilidad</th></tr></thead><tbody><tr><td><code>native</code></td><td>ABI C mediante <code>libloading</code></td><td>Código confiable dentro del proceso; específico del destino</td></tr><tr><td><code>process</code></td><td>Ejecutable independiente, stdin/stdout enmarcado</td><td>Aísla caídas; permisos normales del usuario</td></tr><tr><td><code>napi-vm</code></td><td>JavaScript anticipado sobre QuickJS con <code>rquickjs</code></td><td>Efectos denegados por defecto; addons cambian la confianza</td></tr><tr><td><code>declarative</code></td><td>Descriptores de integración validados</td><td>Sin programa invitado; efectos por el host</td></tr><tr><td><code>wasm</code></td><td>Ranura opcional</td><td>Motor general no activado en compilaciones normales</td></tr></tbody></table><p>La ABI nativa v1 intercambia bytes serializados mediante una tabla C pequeña; no cruzan contenedores Rust, objetos de rasgo ni futuros. Las bibliotecas permanecen cargadas hasta cerrar. El proceso usa longitud u32 little-endian seguida de bytes JSON, no RPC por líneas. Evita escribir diagnósticos en stdout enmarcado.</p><h2 id="understand-quickjs-compatibility" tabindex="-1">Entender la compatibilidad QuickJS <a class="header-anchor" href="#understand-quickjs-compatibility" aria-label="Permalink to &quot;Entender la compatibilidad QuickJS {#understand-quickjs-compatibility}&quot;">​</a></h2><p>El nombre <code>napi-vm</code> permanece estable, pero las afirmaciones de un intérprete Rust separado son históricas. Los invitados reciben globales compatibles documentados, no Node completo. <code>napi_get_uv_event_loop</code> no está admitido. Los addons <code>.node</code> usan una ruta confiable explícita, permitida y verificada con SHA-256 dentro del proceso; el nombre del runtime JavaScript no los vuelve seguros.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-plugin-loader</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lib</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages</span></span></code></pre></div><p>Usa pruebas dirigidas cuando la suite completa de addons requiera herramientas ausentes.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>El analizador rechaza protocolo/ABI incompatibles antes de cargar. Android permite QuickJS portable y ejecutables de proceso Android/Bionic válidos, pero rechaza bibliotecas dinámicas y <code>.node</code>. Un artefacto Linux/glibc de escritorio no sirve como plugin de proceso Android.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Reinicia un host privado tras reemplazar una biblioteca nativa. Si el inicio agota su plazo y queda incierto, el gestor conserva la identidad y bloquea sustituciones; no eludas ese estado declarando cierre correcto. Los buffers de eventos son acotados y pueden informar retraso; emitir durante inicio no constituye una cola duradera. La <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-loader/src" target="_blank" rel="noreferrer">implementación del cargador</a> define motor y ciclo de vida actuales.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Los límites actuales son 512 MiB de memoria QuickJS, pila 2 MiB, presupuesto de interrupción por llamada, tramas 16 MiB y hasta 128 llamadas en cola por instancia. Son límites, no garantía de cancelar efectos. Un proceso agotado se termina/retira; una llamada nativa no se puede matar con seguridad y se conserva la instancia. Sus efectos OS pueden haber ocurrido. Revisa resultado original y ciclo de vida antes de sustituir/reintentar. Addons <code>.node</code> confiables usan privilegios del host, fuera del límite JS.</p>`,16)])])}const h=a(o,[["render",n]]);export{m as __pageData,h as default};
